mapper.select:
/* selectPicList - HeeSung Yoon */ T1.INST_NO, T2.CTPV_NM, T1.INST_NM, T5.DEPT_NM, C##RG.DEC_B64(T4.FLNM_ENCPT) AS FLNM_ENCPT, DECODE(T4.SXDC_SE_CD, 'M', '남', 'F', '여', '') AS SXDC_SE_CD, DECODE(T4.BRTH_YMD, NULL, T3.BRTH_YMD, T4.BRTH_YMD) AS BRTH_YMD, T5.DEPT_TELNO, C##RG.DEC_B64(T4.MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT, T3.ENFSN_NO, T1.PIC_ENFSN_NO FROM SAA000 T1, /* 통합기관 */ SAA020 T2, /* 시군구코드 */ SCA100 T3, /* 종사자 */ SCA300 T4, /* 개인정보 */ SAA300 T5 /* 기관부서 */ WHERE 1=1 AND T1.RGN_CD = T2.SGG_CD AND T1.PIC_ENFSN_NO = T3.ENFSN_NO(+) AND T3.INDV_IDNTFC_NO = T4.INDV_IDNTFC_NO(+) AND T3.OGDP_INST_NO = T5.INST_NO(+) AND T3.OGDP_DEPT_CD = T5.DEPT_CD(+)
AND (T1.INST_NM LIKE '%경찰서' OR T1.INST_NM LIKE '%경찰청') AND T1.UNT_TASKWK_SE_CD = 'U01'
AND T1.INST_NM LIKE '%교육청' AND T1.UNT_TASKWK_SE_CD = 'U03'
AND T4.FLNM_ENCPT = C##RG.ENC_B64(#{FLNM})
AND T2.CTPV_SE_CD = #{CTPV_CD}
AND T2.SGG_CD = #{SGG_CD}
AND T1.INST_NO = #{INST_NO}
AND T4.SXDC_SE_CD = #{SXDC_SE_CD}
AND T1.RGN_CD = #{RGN_CD}

/* 2023-06-20 YOO.CHI.HOON PicMngMapper.selectOfcdcPicList 학교밖청소년지원 교육청 담당자 조회*/ INST_NO , INST_NM , CTPV_SE_CD , CTPV_NM , FLNM_ENCPT , BRTH_YMD , SXDC_SE_CD , DEPT_TELNO , MBL_TELNO_ENCPT , OGDP_DEPT_NM , ENFSN_NO , USER_ID , GROUP_AUTHRT_SE_CD , AUTHRT_SE_CD FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY T1.INST_NO ORDER BY T2.GROUP_AUTHRT_SE_CD) RM , T1.INST_NO , T1.INST_NM , T1.CTPV_SE_CD , T1.CTPV_NM , NVL(C##RG.DEC_B64(T4.FLNM_ENCPT), '') AS FLNM_ENCPT , DECODE(T3.BRTH_YMD, NULL, T4.BRTH_YMD, T3.BRTH_YMD) AS BRTH_YMD , T4.SXDC_SE_CD , DECODE(T3.WRD_TELNO, NULL, T4.WRD_TELNO, T3.WRD_TELNO) AS DEPT_TELNO , NVL(C##RG.DEC_B64(T4.MBL_TELNO_ENCPT), '') AS MBL_TELNO_ENCPT , T3.OGDP_DEPT_NM , T2.ENFSN_NO , T2.USER_ID , T2.GROUP_AUTHRT_SE_CD , T2.AUTHRT_SE_CD FROM (SELECT * FROM SAA000 T1 , SAA020 T2 WHERE T1.RGN_CD = T2.SGG_CD AND T1.UNT_TASKWK_SE_CD = 'U03' AND (T1.INST_NM LIKE '%교육청')) T1 , (SELECT T2.ENFSN_NO , T1.USER_ID , T1.GROUP_AUTHRT_SE_CD , T1.AUTHRT_SE_CD , T1.INST_NO FROM SAB230 T1 , SAA200 T2 WHERE T1.USER_ID = T2.USER_ID AND T1.MAIST_YN = 'Y' AND T2.USER_CNTN_INTRCP_YN = 'N' AND T2.JOIN_APRV_YN = 'Y' AND (T1.GROUP_AUTHRT_SE_CD >= 510 AND T1.GROUP_AUTHRT_SE_CD <= 540)) T2 , SCA100 T3 /* 종사자*/ , SCA300 T4 /* 개인정보*/ WHERE 1 = 1 AND T1.INST_NO = T2.INST_NO(+) AND T2.ENFSN_NO = T3.ENFSN_NO(+) AND T3.INDV_IDNTFC_NO = T4.INDV_IDNTFC_NO(+) AND T3.DEL_YN = 'N' ORDER BY T1.INST_NO ) T WHERE RM = 1
AND T.FLNM_ENCPT = #{FLNM}
AND T.CTPV_SE_CD = #{CTPV_CD}
AND T.SXDC_SE_CD = #{SXDC_SE_CD}

/* 2023-06-21 YOO.CHI.HOON 학교밖청소년지원 경찰서,경찰청 담당자 조회*/ INST_NO , INST_NM , CTPV_SE_CD , CTPV_NM , SGG_CD , FLNM_ENCPT , BRTH_YMD , SXDC_SE_CD , DEPT_TELNO , MBL_TELNO_ENCPT , OGDP_DEPT_NM , ENFSN_NO , USER_ID , GROUP_AUTHRT_SE_CD , AUTHRT_SE_CD FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY T1.INST_NO ORDER BY T2.GROUP_AUTHRT_SE_CD) RM , T1.INST_NO , T1.INST_NM , T1.CTPV_SE_CD , T1.CTPV_NM , T1.SGG_CD , NVL(C##RG.DEC_B64(T4.FLNM_ENCPT), '') AS FLNM_ENCPT , DECODE(T3.BRTH_YMD, NULL, T4.BRTH_YMD, T3.BRTH_YMD) AS BRTH_YMD , T4.SXDC_SE_CD , DECODE(T3.WRD_TELNO, NULL, T4.WRD_TELNO, T3.WRD_TELNO) AS DEPT_TELNO , NVL(C##RG.DEC_B64(T4.MBL_TELNO_ENCPT), '') AS MBL_TELNO_ENCPT , T3.OGDP_DEPT_NM , T2.ENFSN_NO , T2.USER_ID , T2.GROUP_AUTHRT_SE_CD , T2.AUTHRT_SE_CD FROM (SELECT T1.INST_NO , T1.INST_NM , T1.SGG_CD , T1.RGN_CD , T2.CTPV_SE_CD , T2.CTPV_NM FROM SAA000 T1 , SAA020 T2 WHERE T1.RGN_CD = T2.SGG_CD AND T1.UNT_TASKWK_SE_CD = 'U01' AND (T1.INST_NM LIKE '%경찰서' OR T1.INST_NM LIKE '%경찰청')) T1 , (SELECT T2.ENFSN_NO , T1.USER_ID , T1.GROUP_AUTHRT_SE_CD , T1.AUTHRT_SE_CD , T1.INST_NO FROM SAB230 T1 , SAA200 T2 WHERE T1.USER_ID = T2.USER_ID AND T1.MAIST_YN = 'Y' AND T2.USER_CNTN_INTRCP_YN = 'N' AND T2.JOIN_APRV_YN = 'Y' AND (T1.GROUP_AUTHRT_SE_CD >= 410 AND T1.GROUP_AUTHRT_SE_CD <= 440)) T2 , SCA100 T3 /* 종사자*/ , SCA300 T4 /* 개인정보*/ WHERE 1 = 1 AND T1.INST_NO = T2.INST_NO(+) AND T2.ENFSN_NO = T3.ENFSN_NO(+) AND T3.INDV_IDNTFC_NO = T4.INDV_IDNTFC_NO(+) ORDER BY T1.INST_NO ) T WHERE RM = 1
AND T.FLNM_ENCPT = #{FLNM}
AND T.CTPV_SE_CD = #{CTPV_CD}
AND T.SGG_CD = #{SGG_CD}
AND T.INST_NO = #{INST_NO}
AND T.SXDC_SE_CD = #{SXDC_SE_CD}
AND T.RGN_CD = #{RGN_CD}
